module min_insertions (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr [0:7],\n    input wire [3:0] N,\n    input wire [3:0] K,\n    output reg [7:0] result,\n    output reg done\n);\n    // State declarations (4-bit)\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] INIT = 4'd1;\n    localparam [3:0] LOOP_LEN = 4'd2;\n    localparam [3:0] LOOP_L = 4'd3;\n    localparam [3:0] COMP_STATE = 4'd4;\n    localparam [3:0] LOOP_I = 4'd5;\n    localparam [3:0] NEXT_I = 4'd6;\n    localparam [3:0] UPDATE_DP = 4'd7;\n    localparam [3:0] NEXT_K = 4'd8;\n    localparam [3:0] NEXT_L = 4'd9;\n    localparam [3:0] DONE_STATE = 4'd10;\n\n    reg [3:0] state, next_state;\n\n    // DP array\n    reg [7:0] dp [0:7][0:7][0:4];\n\n    // Loop counters\n    reg [3:0] len;\n    reg [3:0] l;\n    reg [3:0] r;\n    reg [3:0] i;\n    reg [3:0] k;\n\n    // Temporary variables\n    reg [7:0] cost1;\n    reg [7:0] cost2;\n    reg [7:0] temp_cost;\n\n    // Precompute some values\n    wire [3:0] end_ptr;\n    assign end_ptr = l + len - 3'd1;\n\n    // Control signals\n    reg init_dp;\n    reg [3:0] iter_limit;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n\n            // Initialize all DP entries\n            for (integer x=0; x<8; x=x+1) begin\n                for (integer y=0; y<8; y=y+1) begin\n                    for (integer z=0; z<5; z=z+1) begin\n                        dp[x][y][z] <= 8'd0;\n                    end\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        len   <= 4'd1;\n                        l     <= 4'd0;\n                        k     <= 4'd0;\n                    end\n                end\n\n                INIT: begin\n                    if (l < N) begin\n                        // Initialize base case (length=1)\n                        if ((k + 4'd1) >= K) begin\n                            dp[l][l][k] <= 8'd0;\n                        end else begin\n                            dp[l][l][k] <= K - (k + 4'd1);\n                        end\n\n                        if (k < (K - 4'd1)) begin\n                            k <= k + 4'd1;\n                        end else begin\n                            k <= 4'd0;\n                            l <= l + 4'd1;\n                        end\n                    end else begin\n                        len <= 4'd2;\n                        l   <= 4'd0;\n                        state <= LOOP_LEN;\n                    end\n                end\n\n                LOOP_LEN: begin\n                    if (len > N) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        l   <= 4'd0;\n                        r   <= len - 4'd1;\n                        state <= LOOP_L;\n                    end\n                end\n\n                LOOP_L: begin\n                    if (l >= (N - len + 4'd1)) begin\n                        len <= len + 4'd1;\n                        state <= LOOP_LEN;\n                    end else begin\n                        k   <= 4'd0;\n                        state <= COMP_STATE;\n                    end\n                end\n\n                COMP_STATE: begin\n                    // Calculate option1\n                    if ((k + 4'd1) >= K) begin\n                        cost1 <= dp[l+4'd1][l+len-4'd2][4'd0];\n                    end else begin\n                        cost1 <= (K - (k + 4'd1)) + dp[l+4'd1][l+len-4'd2][4'd0];\n                    end\n\n                    // Initialize option2\n                    cost2 <= 8'd255;  // Set to maximum\n                    i     <= l + 4'd1;\n                    state <= LOOP_I;\n                end\n\n                LOOP_I: begin\n                    if (i > (l + len - 4'd1)) begin\n                        state <= UPDATE_DP;\n                    end else begin\n                        if (arr[l] == arr[i]) begin\n                            // Calculate temp_cost\n                            if ((k + 4'd1) >= K) begin\n                                temp_cost <= dp[l+4'd1][i-4'd1][4'd0] + dp[i][l+len-4'd1][4'd0];\n                            end else begin\n                                temp_cost <= dp[l+4'd1][i-4'd1][4'd0] + dp[i][l+len-4'd1][k+4'd1];\n                            end\n\n                            state <= NEXT_I;\n                        end else begin\n                            i <= i + 4'd1;\n                        end\n                    end\n                end\n\n                NEXT_I: begin\n                    if (temp_cost < cost2) begin\n                        cost2 <= temp_cost;\n                    end\n                    i <= i + 4'd1;\n                    state <= LOOP_I;\n                end\n\n                UPDATE_DP: begin\n                    dp[l][l+len-4'd1][k] <= (cost1 < cost2) ? cost1 : cost2;\n                    state <= NEXT_K;\n                end\n\n                NEXT_K: begin\n                    if (k < (K - 4'd1)) begin\n                        k <= k + 4'd1;\n                        state <= COMP_STATE;\n                    end else begin\n                        l <= l + 4'd1;\n                        state <= NEXT_L;\n                    end\n                end\n\n                NEXT_L: begin\n                    state <= LOOP_L;\n                end\n\n                DONE_STATE: begin\n                    result <= dp[4'd0][N-4'd1][4'd0];\n                    done  <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n\n